import java.util.*;

import jakarta.persistence.*;
import org.hibernate.cfg.Configuration;

public class Main {
    public static void main(String[] args) {
        EntityManagerFactory emf = Jpa.buat(true, Todo.class);
        EntityManager em = emf.createEntityManager();
        em.getTransaction().begin();
        Todo t = new Todo("Belajar JPA");
        em.persist(t);
        t.ubahJudul("Belajar JPA dan Hibernate");
        t.selesaikan();
        em.getTransaction().commit();
        em.close();
        emf.close();
    }
}

@Entity
class Todo {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String judul;

    private boolean selesai;

    protected Todo() {
    }

    Todo(String judul) {
        this.judul = judul;
    }

    Long getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    void ubahJudul(String judul) {
        this.judul = judul;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

class Jpa {
    static EntityManagerFactory buat(boolean tampilkanSql, Class<?>... entity) {
        Configuration cfg = new Configuration()
                .setProperty("hibernate.connection.url", "jdbc:h2:mem:toko;DB_CLOSE_DELAY=-1")
                .setProperty("hibernate.connection.username", "sa")
                .setProperty("hibernate.hbm2ddl.auto", "create")
                .setProperty("hibernate.show_sql", String.valueOf(tampilkanSql));
        for (Class<?> k : entity) {
            cfg.addAnnotatedClass(k);
        }
        return cfg.buildSessionFactory();
    }
}

