import java.util.*;

import jakarta.persistence.*;
import org.hibernate.cfg.Configuration;

public class Main {
    public static void main(String[] args) {
        EntityManagerFactory emf = Jpa.buat(true, Todo.class);
        EntityManager em = emf.createEntityManager();
        em.getTransaction().begin();
        Todo t = new Todo("Belajar JPA");
        em.persist(t);
        em.getTransaction().commit();
        System.out.println("--- ubah tanpa memanggil method simpan");
        em.getTransaction().begin();
        t.selesaikan();
        em.getTransaction().commit();
        System.out.println("--- object terlepas");
        em.getTransaction().begin();
        Todo kedua = new Todo("Rapat tim");
        em.persist(kedua);
        em.getTransaction().commit();
        em.clear();
        System.out.println("Dikelola? " + em.contains(kedua));
        kedua.ubahJudul("Rapat tim jam 10");
        em.getTransaction().begin();
        Todo dikelola = em.merge(kedua);
        em.getTransaction().commit();
        System.out.println(dikelola + ", dikelola? " + em.contains(dikelola));
        em.close();
        emf.close();
    }
}

