import java.util.*;

import jakarta.persistence.*;
import org.hibernate.cfg.Configuration;

public class Main {
    public static void main(String[] args) {
        EntityManagerFactory emf = Jpa.buat(false, Todo.class);
        Scanner in = new Scanner(System.in);
        EntityManager em = emf.createEntityManager();
        em.getTransaction().begin();
        while (in.hasNextLine()) {
            em.persist(new Todo(in.nextLine()));
        }
        em.getTransaction().commit();
        List<Todo> semua = em.createQuery("select t from Todo t order by t.id", Todo.class).getResultList();
        em.close();

        Todo pertama = semua.get(0);
        pertama.ubahJudul(pertama.getJudul() + " (penting)");
        EntityManager em2 = emf.createEntityManager();
        em2.getTransaction().begin();
        em2.getTransaction().commit();
        em2.close();

        EntityManager em3 = emf.createEntityManager();
        for (Todo t : em3.createQuery("select t from Todo t order by t.id", Todo.class).getResultList()) {
            System.out.println(t);
        }
        em3.close();
        emf.close();
    }
}

